from solution import format_amount
import pytest


def test_examples():
    assert format_amount('1234.5', 'USD') == 'USD 1,234.50'
    assert format_amount('1234.5', 'KRW') == 'KRW 1,235'


def test_negative_half_away():
    assert format_amount('-2.5', 'JPY') == 'JPY -3'
    assert format_amount('-1.005', 'USD') == 'USD -1.01'


def test_negative_zero():
    assert format_amount('-0.004', 'USD') == 'USD 0.00'
    assert format_amount('-0.4', 'KRW') == 'KRW 0'
    assert format_amount('-0.0004', 'BHD') == 'BHD 0.000'


def test_bhd():
    assert format_amount('1234567.8905', 'BHD') == 'BHD 1,234,567.891'


def test_huge():
    assert format_amount('1' * 40 + '.5', 'USD') == 'USD ' + '11,111,111,111,111,111,111,111,111,111,111,111,111,111'[:0] + format(int('1' * 40), ',') + '.50'


def test_huge_krw():
    assert format_amount('9' * 30, 'KRW') == 'KRW ' + format(int('9' * 30), ',')


def test_unknown():
    with pytest.raises(ValueError):
        format_amount('1', 'XYZ')
    with pytest.raises(ValueError):
        format_amount('1', 'usd')


def test_small_grouping():
    assert format_amount('999.995', 'USD') == 'USD 1,000.00'
    assert format_amount('100', 'EUR') == 'EUR 100.00'
    assert format_amount('0', 'KWD') == 'KWD 0.000'


def test_exponent():
    assert format_amount('1E+3', 'USD') == 'USD 1,000.00'
    assert format_amount('1e-7', 'USD') == 'USD 0.00'
